from __future__ import annotations

import json
from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .branding import PRODUCT_FULL_NAME
from .plans import GAME_CREATE

router = APIRouter(tags=["Aura Game World Events Portal"])


@router.get("/game-creation/world-events/{game_id}", response_class=HTMLResponse, include_in_schema=False)
def world_events_portal(game_id: str, request: Request):
    member = getattr(request.state, "member", None)
    if member is None:
        return RedirectResponse(f"/signin?next=/game-creation/world-events/{escape(game_id, quote=True)}", status_code=303)
    if not member.plan.has(GAME_CREATE):
        return RedirectResponse("/game-creation", status_code=303)

    safe_game_id = escape(game_id, quote=True)
    safe_brand = escape(PRODUCT_FULL_NAME)
    game_json = json.dumps(game_id)
    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='robots' content='noindex,nofollow'><title>World Events & Atmosphere — __BRAND__</title><style>
:root{--bg:#04050b;--panel:#0d1220;--line:#ffffff22;--gold:#efca6d;--violet:#986cff;--cyan:#5be1ff;--green:#79dda5;--red:#ff8fa5;--muted:#bcc5d5}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 9% 0,#42165f66,transparent 32%),radial-gradient(circle at 92% 7%,#0e4a6755,transparent 29%),var(--bg);color:#fff;font-family:Inter,system-ui,sans-serif}.wrap{width:min(1320px,calc(100% - 24px));margin:auto}.nav{position:sticky;top:0;z-index:20;background:#05070eef;border-bottom:1px solid var(--line);backdrop-filter:blur(14px)}.navin{min-height:66px;display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.brand{font-weight:950;color:#fff;text-decoration:none}.brand small{display:block;color:var(--gold);font-size:.65rem;letter-spacing:.12em;text-transform:uppercase}.hero{padding:34px 0 18px}.eyebrow{color:var(--gold);font-size:.68rem;font-weight:950;letter-spacing:.14em;text-transform:uppercase}h1{font-size:clamp(2.5rem,6vw,5rem);line-height:.92;letter-spacing:-.05em;margin:.12em 0}.muted{color:var(--muted);line-height:1.55}.grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:12px;padding-bottom:70px}.card{border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,#111729e9,#090d18ee);padding:15px;margin-bottom:12px}.form{display:grid;gap:8px;margin-top:10px}.two{display:grid;grid-template-columns:1fr 1fr;gap:8px}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}input,select,button{font:inherit}input,select{width:100%;border:1px solid var(--line);background:#070a12;color:#fff;border-radius:10px;padding:9px}input[type=color]{padding:3px;min-height:40px}button,.btn{border:1px solid var(--line);background:#ffffff08;color:#fff;border-radius:10px;padding:9px 11px;font-weight:850;cursor:pointer;text-decoration:none}.primary{border:0;background:linear-gradient(120deg,var(--gold),var(--violet));color:#160c1d}.danger{border-color:#ff8fa566;color:#ffd6de}.entry{border:1px solid var(--line);border-radius:12px;padding:11px;margin-top:8px;background:#ffffff05}.row{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.mini{font-size:.75rem;color:var(--muted)}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:3px 7px;font-size:.68rem;margin:2px}.notice{display:none;margin:10px 0;padding:10px;border:1px solid var(--line);border-radius:10px}.notice.show{display:block}.empty{color:var(--muted);padding:14px;border:1px dashed #ffffff2c;border-radius:10px}.safe{border-left:3px solid var(--green)}.audio{border-left:3px solid var(--cyan)}@media(max-width:920px){.grid{grid-template-columns:1fr}}@media(max-width:600px){.two,.three{grid-template-columns:1fr}}
</style></head><body><nav class='nav'><div class='wrap navin'><a class='brand' href='/game-creation'>__BRAND__<small>Aura Game Forge · World Events & Atmosphere</small></a><div><a class='btn' href='/game-creation/gameplay/__GAME_ID__'>Gameplay & Physics</a> <a class='btn' href='/game-creation/adventure/__GAME_ID__'>Adventure State</a> <a class='btn' href='/game-creation/world-logic/__GAME_ID__'>World Logic</a> <button id='scanBtn'>Scan</button> <button id='buildBtn' class='primary'>Build & Play</button></div></div></nav><main class='wrap'><section class='hero'><div class='eyebrow'>Integrity-bound atmosphere and traversal</div><h1 id='title'>World Events & Atmosphere</h1><p class='muted'>Create spawn portals, spatial audio zones and bounded particle emitters from typed World DNA. Audio can only use verified imported game media; runtime networking and arbitrary creator code remain disabled.</p><div id='notice' class='notice'></div></section><section class='grid'><div><div class='card'><div class='eyebrow'>Create World Event</div><h2>Safe preset builder</h2><form id='createForm' class='form'><input id='name' maxlength='160' placeholder='Event name' required><select id='preset'><option value='spawn_portal'>Spawn Portal</option><option value='audio_zone'>Spatial Audio Zone</option><option value='particle_emitter'>Particle Emitter</option></select><div class='three'><input id='x' type='number' step='.1' value='0' aria-label='X'><input id='y' type='number' step='.1' value='0' aria-label='Y'><input id='z' type='number' step='.1' value='0' aria-label='Z'></div><div class='two'><select id='spawnTarget'><option value='spawn'>Target spawn</option></select><select id='audioAsset'><option value=''>Choose imported audio/music</option></select></div><div class='three'><input id='radius' type='number' min='.25' max='100000' step='.25' value='5' aria-label='Audio radius'><input id='volume' type='number' min='0' max='1' step='.05' value='.65' aria-label='Audio volume'><input id='particleColor' type='color' value='#5be1ff' aria-label='Particle color'></div><button class='primary'>Add World Event</button></form></div><div class='card safe'><div class='eyebrow'>Runtime safety</div><h3>No arbitrary scripts or external media</h3><p class='muted'>Portals can teleport only to existing World spawn entities. Audio zones can reference only imported audio/music snapshots and require the player to enable world audio. Particle rate, lifetime, speed, size and total count are clamped before runtime.</p></div><div class='card audio'><div class='eyebrow'>Audio contract</div><p class='muted'>World Audio is same-origin, integrity-bound media. No creator URL field exists, and public-test media is copied from the checksum-verified private snapshot.</p></div></div><div><div class='card'><div class='row'><div><div class='eyebrow'>Current World Events</div><h2>Authored event entities</h2></div><button id='refreshBtn'>Refresh</button></div><div id='events'><div class='empty'>Loading…</div></div></div><div class='card'><div class='eyebrow'>Convert existing entity</div><h3>Apply a safe event preset</h3><form id='applyForm' class='form'><select id='entity'><option value=''>Choose non-core World entity</option></select><select id='applyPreset'><option value='spawn_portal'>Spawn Portal</option><option value='audio_zone'>Spatial Audio Zone</option><option value='particle_emitter'>Particle Emitter</option></select><button>Apply World Event preset</button></form><p class='mini'>The target spawn, audio asset, radius, volume and particle color above are reused when applying this preset.</p></div></div></section></main><script>
'use strict';const GAME_ID=__GAME_JSON__;const $=id=>document.getElementById(id);function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function notice(v,bad=false){const e=$('notice');e.textContent=v;e.className='notice show';e.style.borderColor=bad?'#ff8fa566':'#79dda566';clearTimeout(window.__eventNotice);window.__eventNotice=setTimeout(()=>e.className='notice',6500)}async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch{}if(!r.ok)throw new Error(typeof b.detail==='string'?b.detail:(b.detail?.message||`Request failed (${r.status})`));return b}
function eventBody(preset){return{preset,target_spawn_id:$('spawnTarget').value||null,audio_asset_id:$('audioAsset').value||null,radius:Number($('radius').value||5),volume:Number($('volume').value||.65),particle_color:$('particleColor').value||'#5be1ff'}}
function renderEvents(state){const rows=state.entities||[];$('events').innerHTML=rows.map(row=>{const ops=(row.behaviors||[]).map(b=>b.op).join(', ');return`<article class='entry'><div class='row'><div><b>${esc(row.name)}</b><div class='mini'>${esc(row.id)}</div></div><button class='danger deleteEvent' data-id='${esc(row.id)}'>Delete</button></div><span class='pill'>${esc(row.kind)}</span><span class='pill'>${esc(ops||'event')}</span><div class='mini'>${row.physics?`Physics: ${esc(row.physics.mode)}`:'Logic-only / atmosphere entity'}</div></article>`}).join('')||'<div class="empty">No World Events authored yet.</div>';document.querySelectorAll('.deleteEvent').forEach(btn=>btn.addEventListener('click',()=>removeEvent(btn.dataset.id)))}
async function load(){try{const [game,state,world,assets]=await Promise.all([api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}`),api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/world-events`),api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/world`),api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/assets`)]);$('title').textContent=`${game.title} · World Events & Atmosphere`;renderEvents(state);const worldRows=world.world?.entities||[],spawnRows=worldRows.filter(e=>e.kind==='spawn'),audioRows=(assets.assets||[]).filter(a=>a.kind==='audio'||a.kind==='music');const oldSpawn=$('spawnTarget').value,oldAudio=$('audioAsset').value,oldEntity=$('entity').value;$('spawnTarget').innerHTML=spawnRows.map(e=>`<option value='${esc(e.id)}'>${esc(e.name)} · ${esc(e.id)}</option>`).join('')||'<option value="spawn">Default spawn</option>';$('audioAsset').innerHTML='<option value="">Choose imported audio/music</option>'+audioRows.map(a=>`<option value='${esc(a.id)}'>${esc(a.label)} · ${esc(a.kind)}</option>`).join('');$('entity').innerHTML='<option value="">Choose non-core World entity</option>'+worldRows.filter(e=>!['player','camera','spawn'].includes(e.id)).map(e=>`<option value='${esc(e.id)}'>${esc(e.name)} · ${esc(e.id)}</option>`).join('');if([...$('spawnTarget').options].some(o=>o.value===oldSpawn))$('spawnTarget').value=oldSpawn;if([...$('audioAsset').options].some(o=>o.value===oldAudio))$('audioAsset').value=oldAudio;if([...$('entity').options].some(o=>o.value===oldEntity))$('entity').value=oldEntity}catch(e){notice(e.message,true)}}
$('createForm').addEventListener('submit',async e=>{e.preventDefault();try{const body={name:$('name').value,position:{x:Number($('x').value||0),y:Number($('y').value||0),z:Number($('z').value||0)},scale:{x:1,y:1,z:1},...eventBody($('preset').value)};body.preset=$('preset').value;await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/world-events/entities`,{method:'POST',body:JSON.stringify(body)});notice('World Event added; previous build/rating invalidated.');$('name').value='';await load()}catch(err){notice(err.message,true)}});
$('applyForm').addEventListener('submit',async e=>{e.preventDefault();if(!$('entity').value)return notice('Choose a World entity first.',true);try{const body=eventBody($('applyPreset').value);body.preset=$('applyPreset').value;await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/world-events/entities/${encodeURIComponent($('entity').value)}/preset`,{method:'POST',body:JSON.stringify(body)});notice('World Event preset applied.');await load()}catch(err){notice(err.message,true)}});
async function removeEvent(id){if(!id||!confirm('Delete this authored World Event?'))return;try{await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/world-events/entities/${encodeURIComponent(id)}`,{method:'DELETE'});notice('World Event deleted; previous build/rating invalidated.');await load()}catch(e){notice(e.message,true)}}
$('refreshBtn').addEventListener('click',load);$('scanBtn').addEventListener('click',async()=>{try{const r=await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/scan`,{method:'POST'});notice(r.public_test_allowed?'Integrity/rating scan passed.':`Scan completed with ${(r.blockers||[]).length} blocker(s).`,!r.public_test_allowed)}catch(e){notice(e.message,true)}});$('buildBtn').addEventListener('click',async()=>{try{const r=await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/build`,{method:'POST'});notice(`Built ${r.runtime}. Opening private playtest…`);window.open(r.private_playtest_url,'_blank','noopener')}catch(e){notice(e.message,true)}});load();
</script></body></html>"""
    html = html.replace("__BRAND__", safe_brand).replace("__GAME_ID__", safe_game_id).replace("__GAME_JSON__", game_json)
    return HTMLResponse(html)


__all__ = ["router"]
